message.content:
{
  "description": "The creature is shown in right-facing profile standing upright on two hind legs against a plain off-white background. The anterior head, neck, hind legs and long tail have the appearance of a reddish-brown fox with dense fur, while the torso, chest and paired folded wings have the appearance of an owl with layered brown, tan, grey and white feathers. The head is fox-like with a pointed muzzle, the body is stout and upright, the wings are folded close against the sides of the body, and the tail extends straight back behind the legs. The overall coloration is reddish-brown on the head, outer legs and tail, white on the muzzle, throat and chest, and mottled tan, grey and brown with dark speckling and barring on the back and wings.",
  "parts": [
    {
      "part": "head",
      "looks_like": "fox-like, narrow pointed muzzle with a black nose, white fur around the muzzle and lower cheek, reddish-brown fur on the top of the muzzle and forehead, a visible amber-brown eye with a dark pupil facing right, and fine whiskers on the muzzle",
      "where": "at the top front of the body, in profile facing right"
    },
    {
      "part": "ears",
      "looks_like": "two upright, triangular pointed ears with reddish-brown outer fur, black on the back edges and pale buff inside, with dark inner fur",
      "where": "on top of the head, one slightly in front of the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in short reddish-brown fur that darkens to dark brown-black on the lower shins, with visible hock joints bent in a standing posture",
      "where": "under the rear torso, extending down to the ground, left and right hind legs visible in profile with the nearer leg in front"
    },
    {
      "part": "feet",
      "looks_like": "dark brown to black paws with blunt claws and padded soles, the toes splayed slightly on the ground",
      "where": "at the bottom ends of the two hind legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick and bushy, covered in long reddish-brown fur with darker underfur and a pale cream-white tip at the end",
      "where": "extending from the rear of the body, angled slightly downward behind the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "two folded bird wings with layered flight feathers, the nearer wing prominently visible with broad overlapping feathers showing tan, cream, grey and brown coloration, dark speckles and dark barring on the primaries, the farther wing partially visible under the chest",
      "where": "folded against the sides of the torso, from the shoulder region above the mid-back down to the upper thigh, one on the near side and one on the far side"
    },
    {
      "part": "feathers",
      "looks_like": "dense, soft-looking owl-like plumage covering the neck, back, chest, belly and wings; white with small dark spots on the throat, chest and belly, and mottled tan, buff, grey and brown with scalloped feather edges on the back and wing coverts",
      "where": "covering the entire torso from the back of the neck down the back and around the front chest and belly, and forming the wings"
    },
    {
      "part": "markings",
      "looks_like": "small black-brown spots scattered on the white chest and belly, darker brown barring and chevron marks on the wing and tail feathers, and grey scalloping on the back and shoulder feathers",
      "where": "on the white chest/belly plumage, on the folded wing feathers along the side, and on the dorsal back feathers behind the neck"
    }
  ],
  "attached_objects": [],
  "animals": [
    "fox",
    "barn owl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
